  "Elo minimum · chaque joueur": "Minimo Elo · para cada jogador",
  "Elo maximum · chaque joueur": "Maximo Elo · por jogador",
  "Sans minimum": "Não há mínimo",
  "Cadences du PGN": "PGN Controle de tempo",
  "Sans maximum": "Não máximo",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "Nenhuma seleção = todos os controles de tempo, incluindo os desconhecidos.",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "O Elo vem do PGN e deve estar dentro da faixa para ambos os jogadores. Os jogos de xadrez sem Elo são excluídos quando um limite é definido. Os controles de tempo PGN desaparecidos ou não reconhecidos são \"Inconhecidos\". Estes jogos de xadrez são excluídos quando os controles de tempo são selecionados, a menos que seja selecionado \"Inconhecido\".",
  ": indique un nombre valide pour la borne Elo.": ": inserir um número válido para a linha Elo.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": inserir um número inteiro Elo de 0 a 4000, ou deixar o ponto em branco.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": o mínimo Elo não pode exceder o máximo Elo.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "Criar um banco de dados e importar PGN jogos de xadrez na biblioteca.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess masters não tem Elo ou filtros de controlo do tempo. Para filtrar uma coleção principal, escolha um banco de dados importado, como o Mega Database.",
  "Source principale": "Fonte principal",
  "Mes bases PGN": "As minhas bases de dados PGN",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "Apenas os movimentos de xadrez de linha principal são contados. As variações da análise não inflacionam as estatísticas.",
  "Référence dans chaque ligne": "Referência em cada linha",
  "Comparer avec": "Comparar com",
  "Mes bases de référence": "As minhas bases de dados de referência",
  "Aucune référence": "Não há referência",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "Estes filtros são independentes da base de dados principal. A percentagem mostra a frequência de movimentos de xadrez nesta posição na referência escolhida.",
  "Probabilité de rencontre": "Probabilidade de encontro",
  "Afficher la probabilité de la ligne": "Mostre probabilidade de linha",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "Escolha o seu lado diretamente no explorador. Apenas as respostas do adversário contam; os seus movimentos de xadrez são assumidos. Esta estimativa segue a variação exibida e os filtros de base de dados selecionados. Para um PGN a partir de um diagrama, depende dessa posição de partida.",
  "Mode d’analyse": "Modo de análise",
  "Rapide (~250 ms par coup)": "Rapido (~ 250 ms por jogada de xadrez)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "A profundidade mais elevada aperfeiçoia a análise e leva mais tempo. De 8 a 30, com um limite de 10 segundos por movimento de xadrez. Se o objectivo não for atingido, ≈ marca o resultado; balança para ver a sua profundidade real.",
