  "Les acquis restent conservés. Les premiers rappels des anciennes cartes sont répartis dans le temps, sous ce plafond quotidien. Une erreur remet la carte en apprentissage.": "O seu progresso está preservado. Os lembretes iniciais para os cartões existentes são distribuídos ao longo do tempo dentro deste limite diário. Um erro devolve o cartão à aprendizagem.",
