  "Équilibré (recommandé)": "Equilibrado (recomendado)",
  "Les profils recommandés laissent de la capacité pour les autres applications. Choisis Personnalisé pour ajuster les valeurs.": "Os perfis recomendados deixam capacidade para outras aplicações. Escolhe Personalizado para ajustar os valores.",
  "Budget CPU (cœurs logiques)": "Orçamento de CPU (núcleos lógicos)",
  "Cache mémoire Stockfish total (Mo)": "Cache de memória total do Stockfish (MB)",
  "Le cache mémoire est partagé entre les deux moteurs Stockfish. Ce réglage ne plafonne pas la RAM totale de ChessGym : Maia, les imports et l’interface utilisent aussi de la mémoire.": "A cache de memória é partilhada entre os dois motores Stockfish. Esta definição não limita a RAM total do ChessGym: o Maia, as importações e a interface também utilizam memória.",
  "Le budget CPU est partagé entre les calculs et les imports. Les tâches attendent si le budget est déjà utilisé. Les changements s’appliquent aux prochaines tâches.": "O orçamento de CPU é partilhado entre os cálculos e as importações. As tarefas aguardam se o orçamento já estiver em utilização. As alterações aplicam-se às próximas tarefas.",
  "La configuration enregistrée a été adaptée aux ressources de ce serveur.": "A configuração guardada foi adaptada aos recursos deste servidor.",
