  "La profondeur doit être un entier positif compatible avec le moteur.": "A profundidade deve ser um número inteiro positivo compatível com o motor.",
  "Le temps par position doit être un entier d’au moins 100 ms, représentable sans perte.": "O tempo por posição deve ser um número inteiro de pelo menos 100 ms que possa ser representado sem perda de precisão.",
  "Choisis une durée ou une profondeur pour analyser la partie.": "Escolhe uma duração ou uma profundidade para analisar a partida.",
  "Choisis une profondeur positive. Le calcul continue jusqu’à cette cible, sans limite de temps ajoutée. Une profondeur élevée peut demander longtemps ; tu peux arrêter les évaluations ou changer de position.": "Escolhe uma profundidade positiva. O cálculo continua até esse objetivo, sem acrescentar um limite de tempo. Uma profundidade elevada pode demorar bastante; podes parar as avaliações ou mudar de posição.",
  "Choisis une profondeur entière positive compatible avec le moteur.": "Escolhe uma profundidade inteira positiva compatível com o motor.",
  ", sans limite de temps ajoutée. ≈ indique une cible non atteinte.": ", sem acrescentar um limite de tempo. ≈ indica um objetivo não atingido.",
  " non atteinte": " não atingida",
  "Durée par position": "Tempo por posição",
  "En mode profondeur, chaque position est analysée jusqu’à la cible, sans limite de temps ajoutée. En mode durée, le calcul utilise le temps choisi. Tu peux continuer à utiliser ChessGym ou annuler le bilan.": "No modo de profundidade, cada posição é analisada até ao objetivo, sem acrescentar um limite de tempo. No modo de duração, o cálculo utiliza o tempo escolhido. Podes continuar a utilizar o ChessGym ou cancelar o relatório.",
  "Choisis une durée d’au moins 0,1 seconde, avec au plus trois décimales.": "Escolhe uma duração de pelo menos 0,1 segundos, com um máximo de três casas decimais.",
